#!/usr/bin/env python3
"""
Round 211o (culprits), 15 October 2026. Needs round 210o.

Way back under Snap back in the Moon/Mars views; light, anti-gravity and gravity assists under From Earth.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 211o (15 October)\n\nNeeds round 210o (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- The Moon, Mars and other views: under Snap back to global scale, in this\n  order: Back to the solar system, Back to Earth, then To Mars (from the\n  Moon) or To the Moon (from Mars), both from the other views. They message\n  the map (culpritsNav); the map\'s own floating Back to Earth and Moon/Mars/\n  Sun buttons are hidden while a view is open.\n- Rows moved: Light reaching Earth, Anti-gravity and Gravity assists to a\n  new heading under From Earth ("Light, anti-gravity and gravity assists");\n  To Earth keeps "Gravity reaching Earth" (gravity reaching Earth, Earth\'s\n  gravity reach).\n\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round211o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 210o" not in h.read_text(encoding="utf-8"):
        sys.exit("round211o: round 210o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round211o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/index.html", "map/bodies.html", "map/test.mjs", "map/atlas-plate.webp", check=False)
            sys.exit("round211o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round211o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
